"""Self-contained apply script - run from inside your HealthCross project
folder (the one with .venv in it): python3 apply_claims_comparison_burning_cost.py
Writes/overwrites the files below, then git add/commit/push yourself.

After running this, verify it actually took before restarting the server:
  grep -n "burning_cost_per_member" app/api/routes_analysis.py
should print several lines. If it prints nothing, something went wrong -
do not restart the server yet, re-run this script and check again first.
"""
import base64, hashlib, os

FILES = {
    'app/api/routes_analysis.py': '',
    'app/static/index.html': '',
    'tests/test_api_claims_report_analysis.py': '',
}

CHECKSUMS = {
    'app/api/routes_analysis.py': 'ccd137d3c9e55697c5a1a380c425d4906edbd501e052a894c65d14f70d3084b3',
    'app/static/index.html': '7bc217d41700f2f6600dfd264fe0bb6114116c2bcda0b54bf5e44b34b297b784',
    'tests/test_api_claims_report_analysis.py': 'f8f04b714495af291aa05438ce1850317231e97e3a199c151ce3c619b73bd90d',
}


SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))

def main():
    for relpath, b64 in FILES.items():
        target = os.path.join(SCRIPT_DIR, relpath)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        data = base64.b64decode(b64)
        with open(target, "wb") as f:
            f.write(data)
        actual = hashlib.sha256(data).hexdigest()
        expected = CHECKSUMS[relpath]
        status = "OK" if actual == expected else "CHECKSUM MISMATCH - something is wrong!"
        print(f"Wrote {relpath} ({len(data)} bytes) - {status}")
    print()
    print("Now verify it actually landed before doing anything else:")
    print('  grep -n "burning_cost_per_member" app/api/routes_analysis.py')
    print("(should print several lines - if empty, do not proceed, tell Claude)")
    print()
    print("Then run:")
    print("  git add -A")
    print('  git commit -m "Add burning cost and year-over-year % change to claims report comparison"')
    print("  git push -u origin claude/underwriting-intelligence-tools-v0xh0j")

if __name__ == "__main__":
    main()
